// Built-in component library in the v2 vocabulary (same names/categories as v1).
// `{{assets}}` resolves to the module's assets URL. Previews are generated by
// scripts/generate-previews.ts; tests require every component to survive sanitization unchanged.
import type { ComponentDefinition } from '../context'
import { h, img, link, section, type Vars } from './builder'

const INK = '#111827'
const MUTED = '#4b5563'
const SUBTLE = '#6b7280'
const LIGHT = '#f3f4f6'
const ACCENT = '#10b981'
const ACCENT_SOFT = '#ecfdf5'

const PAGE: Vars = { '--pad-y': '5rem', '--pad-x': '1.5rem' }
const wrap = (vars: Vars, ...children: string[]) => h('div', 'wrap', vars, ...children)
const stack = (vars: Vars, ...children: string[]) => h('div', 'stack', vars, ...children)
const grid = (vars: Vars, ...children: string[]) => h('div', 'grid', vars, ...children)
const cell = (vars: Vars, ...children: string[]) => h('div', 'span', vars, ...children)
/** A grid cell that is also a stack, so its background fills the whole row. */
const cellStack = (vars: Vars, ...children: string[]) => h('div', 'span stack', vars, ...children)

const eyebrow = (text: string, color = ACCENT) =>
  h('p', '', { '--fs': '0.875rem', '--fw': '600', '--fg': color }, text)
const title = (text: string, vars: Vars = {}) =>
  h(
    'h2',
    '',
    { '--fs': '1.875rem', '--fs-md': '2.25rem', '--fw': '700', '--lh': '1.2', ...vars },
    text,
  )
const body = (text: string, vars: Vars = {}) =>
  h('p', '', { '--fs': '1.125rem', '--fg': MUTED, '--lh': '1.75', ...vars }, text)
const small = (text: string, vars: Vars = {}) =>
  h('p', '', { '--fs': '0.875rem', '--fg': SUBTLE, ...vars }, text)
const avatar = (size: string) =>
  h('div', 'wrap', { '--max': size }, img({ '--h': size, '--r': '9999px' }, 'Portrait'))
const person = (name: string, role: string, size = '8rem', color = INK) =>
  stack(
    { '--gap': '0.5rem', '--align': 'center' },
    avatar(size),
    h('h3', '', { '--fw': '600', '--fg': color }, name),
    small(role),
  )

